import assert from 'node:assert/strict';
import test from 'node:test';

import { Context } from '@deepseek-ai/cordis';
import { installModelSelection } from '@deepseek-ai/dsh-agent';
import * as plugin from '../lib/index.js';

const previous = { provider: 'test-provider', model: 'gpt-5.6-sol' };
const selected = { provider: 'test-provider', model: 'gpt-6.1-sol' };
const noticeText =
  '[model changed: assistant turns above this point were generated by gpt-5.6-sol; the session continues with gpt-6.1-sol]';

function makeAgent(ctx) {
  return {
    id: 'test-session',
    ctx,
    session: { requestHeader: () => ({ config: previous }) },
  };
}

function makePayload(agent, messages, overrides = {}) {
  return {
    agent,
    messages,
    turn: 1,
    step: 1,
    signal: new AbortController().signal,
    modelSelection: selected,
    ...overrides,
  };
}

function userMessage(text) {
  return Object.freeze({
    role: 'user',
    content: Object.freeze([Object.freeze({ type: 'text', text })]),
    source: Object.freeze({ kind: 'user' }),
  });
}

async function installBuiltin(ctx) {
  const fiber = ctx.plugin({
    name: 'test-builtin-model-selection',
    apply: installModelSelection,
  });
  await fiber;
  return fiber;
}

async function admit(ctx, agent, messages, overrides = {}) {
  const decision = { kind: 'enter', messages, startsRequestSeries: true };
  let nextCalls = 0;
  const result = await ctx.waterfall(
    'agent/pre-step',
    makePayload(agent, messages, overrides),
    async () => {
      nextCalls += 1;
      return decision;
    },
  );
  assert.equal(nextCalls, 1);
  assert.equal(result.kind, 'enter');
  assert.equal(result.startsRequestSeries, true);
  return result;
}

test('the real DSH listener produces the reported text with a model-selection source', async () => {
  const ctx = new Context();
  const builtin = await installBuiltin(ctx);
  const agent = makeAgent(builtin.ctx);
  const messages = [userMessage('continue')];

  try {
    const result = await admit(ctx, agent, messages);
    assert.equal(result.messages.length, 2);
    assert.strictEqual(result.messages[0], messages[0]);
    const notice = result.messages[1];
    assert.equal(notice.role, 'user');
    assert.equal(typeof notice.id, 'string');
    assert.deepEqual(notice.content, [{ type: 'text', text: noticeText }]);
    assert.equal(notice.source.kind, 'model-selection');
    assert.equal(notice.source.form, 'notice');
    assert.equal(notice.source.summary, 'gpt-5.6-sol → gpt-6.1-sol');
  } finally {
    await builtin.dispose();
  }
});

test('removes a real notice when enabled after an existing agent was set up', async () => {
  const ctx = new Context();
  const builtin = await installBuiltin(ctx);
  const silent = ctx.plugin(plugin);
  await silent;
  const agent = makeAgent(builtin.ctx);
  const messages = Object.freeze([userMessage('continue')]);

  try {
    const result = await admit(ctx, agent, messages);
    assert.deepEqual(result.messages, messages);
    assert.strictEqual(result.messages[0], messages[0]);
    assert.equal(messages.length, 1);
  } finally {
    await silent.dispose();
    await builtin.dispose();
  }
});

for (const source of ['startup', 'resume']) {
  test(`removes a real notice for an agent announced with source ${source} after plugin activation`, async () => {
    const ctx = new Context();
    const silent = ctx.plugin(plugin);
    await silent;
    const builtin = await installBuiltin(ctx);
    const agent = makeAgent(builtin.ctx);
    const messages = [userMessage('continue')];

    try {
      await ctx.serial('agent/created', { agent, source });
      const result = await admit(ctx, agent, messages);
      assert.deepEqual(result.messages, messages);
      assert.strictEqual(result.messages[0], messages[0]);
    } finally {
      await silent.dispose();
      await builtin.dispose();
    }
  });
}

test('preserves identical user-authored notice text while removing the internal notice', async () => {
  const ctx = new Context();
  const builtin = await installBuiltin(ctx);
  const silent = ctx.plugin(plugin);
  await silent;
  const agent = makeAgent(builtin.ctx);
  const messages = [userMessage(noticeText)];

  try {
    const result = await admit(ctx, agent, messages);
    assert.deepEqual(result.messages, messages);
    assert.strictEqual(result.messages[0], messages[0]);
  } finally {
    await silent.dispose();
    await builtin.dispose();
  }
});

test('lifecycle reordering keeps one filter and plugin disposal removes it', async () => {
  const ctx = new Context();
  const silent = ctx.plugin(plugin);
  await silent;
  const builtin = await installBuiltin(ctx);
  const agent = makeAgent(builtin.ctx);
  const messages = [userMessage('continue')];

  try {
    for (let i = 0; i < 10; i += 1) {
      await ctx.serial('agent/created', { agent, source: 'startup' });
    }
    const effects = silent.getEffects();
    assert.equal(
      effects.filter((effect) => effect.label === 'ctx.on("agent/pre-step")').length,
      1,
    );
    const filtered = await admit(ctx, agent, messages);
    assert.deepEqual(filtered.messages, messages);

    await silent.dispose();
    await ctx.serial('agent/created', { agent, source: 'resume' });
    const unfiltered = await admit(ctx, agent, messages);
    assert.equal(unfiltered.messages.length, 2);
    assert.equal(unfiltered.messages[1].source.kind, 'model-selection');
  } finally {
    await silent.dispose();
    await builtin.dispose();
  }
});

test('keeps an enter decision when a real notice is the only continuation message', async () => {
  const ctx = new Context();
  const builtin = await installBuiltin(ctx);
  const silent = ctx.plugin(plugin);
  await silent;
  const agent = makeAgent(builtin.ctx);

  try {
    const result = await admit(ctx, agent, [], { step: 2 });
    assert.deepEqual(result.messages, []);
  } finally {
    await silent.dispose();
    await builtin.dispose();
  }
});
